import { useRef } from "react";
import useTooltip from "../../hooks/useTooltip";
import { Link } from "react-router-dom";

const ProjectCard = ({ element }) => {
    const imgRef = useRef(null);
    const {
        tooltip,
        pos,
        showTooltip,
        moveTooltip,
        hideTooltip
    } = useTooltip();

    return (
        <div className="projects__card">
        <Link
            to={`/projects/${element.slug}`}
            className="projects__img-wrapper"
            onMouseEnter={(e) => showTooltip(e, imgRef, element.type)}
            onMouseMove={moveTooltip}
            onMouseLeave={hideTooltip}
        >
            <img
                ref={imgRef}
                src={element.image}
                alt={element.alt}
                crossOrigin="anonymous"
                loading="lazy"
            />
            <svg
                className="projects__arrow"
                width="14"
                height="14"
                viewBox="0 0 14 14"
            >
                <path d="M10.8101 1.96222L0.726954 12.0453L1.66171 12.9801L11.7448 2.89698L11.9344 9.4447L13.208 9.07311L13.0134 2.35278C12.9877 1.46249 12.2434 0.718185 11.3531 0.692412L4.80762 0.502924L4.43487 1.77539L10.8101 1.96222Z" fill="white" stroke="white" strokeWidth="0.542084"/>
            </svg>
            {tooltip && (
                <div
                    className="projects__tooltip"
                    style={{
                        backgroundColor: tooltip.bg,
                        color: tooltip.color,
                        top: pos.y + 16,
                        left: pos.x + 16,
                    }}
                >
                    {tooltip.text}
                </div>
            )}
        </Link>
            <div className="projects__title">
                <h3 className="text-h3">
                    {element.title}
                </h3>
                <p className="text-body-lg chivo">
                    ×
                </p>
                <Link
                    className="projects__link"
                    to={`projects/${element.slug}`}
                >
                    <h3 className="projects__type text-h3">
                        {element.with}
                    </h3>
                </Link>
            </div>
        </div>
    );
};

const Projects = ({ items }) => {
    return (
        <section className="projects">
            <div className="projects__header">
                <p className="text-small">
                    This is my
                </p>
                <h2 className="text-h2 inter_tight">
                    PROJECTS
                </h2>
                <p className="text-small">
                    Computer Science
                </p>
            </div>

            <div className="projects__grid">
                {items.slice(0, 6).map((element, index) => (
                    <ProjectCard
                        key={element.id}
                        element={element}
                    />
                ))}
            </div>
            <div className="view_all">
                <Link
                    to={`/projects`}
                >
                    <p>Check my all projects</p>
                    <svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" viewBox="0 0 24 24">
                        <path d="M0 0h24v24H0z" fill="none" />
                        <path fill="none" stroke="#000" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" d="M4 12h16m0 0l-6-6m6 6l-6 6" />
                    </svg>
                    <p className="projects__link">View All </p>
                </Link>
            </div>
        </section>
    );
};

export default Projects;
